import{_ as t,g as a,e as o,a4 as r}from"./chunks/framework.CEYJDsBW.js";const p=JSON.parse('{"title":"Hand Order, Amulet Boxes, and Built-in Totems","description":"","frontmatter":{},"headers":[],"relativePath":"en/anvilcraft/21.1/totems/box.md","filePath":"en/anvilcraft/21.1/totems/box.md"}'),n={name:"en/anvilcraft/21.1/totems/box.md"};function i(s,e,d,l,c,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="hand-order-amulet-boxes-and-built-in-totems" tabindex="-1">Hand Order, Amulet Boxes, and Built-in Totems <a class="header-anchor" href="#hand-order-amulet-boxes-and-built-in-totems" aria-label="Permalink to &quot;Hand Order, Amulet Boxes, and Built-in Totems&quot;">​</a></h1><p>To allow the Ember Ward to be placed into an amulet box as well, add an item tag for <code>workshop:ember_ward</code>. Write the file below to <code>data/anvilcraft/tags/item/totem.json</code>; once the server reloads data, the box recognizes the registered Ember Ward.</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;replace&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;values&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;workshop:ember_ward&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]}</span></span></code></pre></div><p>Death protection checks the main hand first, then the offhand. Players also check an amulet box in their pocket; a standalone totem placed in the pocket does not enter this candidate list. For each matched item, the outer <code>canExecute</code> is called first, followed by <code>CommonHooks.onLivingUseTotem</code>. A pocket box also reports as the offhand to that hook. The first item passing both checks claims this attempt exclusively.</p><p>The box&#39;s <code>canExecute</code> only checks that its totem list is non-empty. <code>execute</code> takes the first item in the list, looks up the handler by item, and calls its <code>execute</code> directly. On success, the box&#39;s <code>shrink</code> converts <code>BoxContents</code> to a mutable copy, removes the first entry, and writes it back to <code>BOX_CONTENTS</code>. Even if the second totem could activate, failure on the first does not fall through to it. Scroll selection picks which item the player wants to take out, whereas death protection always takes the head of the queue. <a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/api/totem/handler/AmuletBoxHandler.java" target="_blank" rel="noreferrer">Amulet box handler</a> · <a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/item/property/component/BoxContents.java" target="_blank" rel="noreferrer">Capacity &amp; extraction</a></p><table tabindex="0"><thead><tr><th>Built-in Handler</th><th>When It Succeeds</th><th>Outcome</th></tr></thead><tbody><tr><td><code>TotemOfUndyingHandler</code></td><td>Damage does not belong to <code>BYPASSES_INVULNERABILITY</code>.</td><td>Sets health to <code>1</code>, clears totem-curable effects, grants Regeneration, Absorption, and Fire Resistance, and plays entity event <code>35</code>.</td></tr><tr><td><code>TotemOfRecoveryHandler</code></td><td>Damage is not <code>GENERIC_KILL</code>.</td><td>Restores the same base state as the Totem of Undying. Server players also receive a Recovery Pearl, record their death position, and teleport to their respawn point.</td></tr><tr><td><code>TotemOfRageHandler</code></td><td>Damage does not belong to <code>BYPASSES_INVULNERABILITY</code>.</td><td>Restores full health, clears effects, and applies Rage and related effects; triggered entities undergo duration checks on subsequent <code>baseTick</code>s. Survival or adventure players die when the duration expires.</td></tr></tbody></table><p><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/api/totem/handler/TotemOfUndyingHandler.java" target="_blank" rel="noreferrer">Undying</a> · <a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/api/totem/handler/TotemOfRecoveryHandler.java" target="_blank" rel="noreferrer">Recovery</a> · <a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/api/totem/handler/TotemOfRageHandler.java" target="_blank" rel="noreferrer">Rage</a> · <a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/mixin/LivingEntityMixin.java" target="_blank" rel="noreferrer">Rage timer &amp; candidate order</a></p>',7)])])}const m=t(n,[["render",i]]);export{p as __pageData,m as default};
